sub(p,"""  it('cancelling an appointment prevents""","""  it('does not charge the consultation again for a follow-up with the same practitioner within 30 days', async () => {
    async function completeVisit(startsAt: string, completeAt: string, procedureCodes: string[]) {
      const appointmentId = await scheduleAppointment('person-50', startsAt);
      clock.set(new Date(new Date(startsAt).getTime() - 10 * 60_000));
      await http().post(`/front-desk/visits/${appointmentId}/check-in`).expect(200);
      const encounter = await http().get('/clinical/encounters').query({ appointmentId }).expect(200);
      await http().post(`/clinical/encounters/${encounter.body.id}/start`).expect(200);
      clock.set(new Date(completeAt));
      await http().post(`/clinical/encounters/${encounter.body.id}/complete`).send({ procedureCodes }).expect(200);
      return encounter.body.id as string;
    }

    await completeVisit('2026-03-02T10:00:00.000Z', '2026-03-02T10:30:00Z', ['10101012']);
    const followUpId = await completeVisit('2026-03-16T10:00:00.000Z', '2026-03-16T10:30:00Z', [
      '10101012',
      '40304361',
    ]);

    const invoices = await http().get('/billing/invoices').query({ payerId: 'person-50' }).expect(200);
    expect(invoices.body).toHaveLength(2);
    expect(invoices.body[1]).toMatchObject({
      source: { type: 'ENCOUNTER', id: followUpId },
      totalCents: 3_500,
      lines: [expect.objectContaining({ code: '40304361' })],
    });
  });

  it('cancelling an appointment prevents""")
